sp_widget.client_script:
api.controller = function($scope, $rootScope, $window, spUtil) {

  /* =========================================================
     GATENOW · MY PROJECTS · Client script

     Tabs, search and the modal all run against data already on
     the page. No writes, so nothing goes back to the server.
     ========================================================= */

  var c = this;

  c.query = '';
  c.tab   = 'all';

  /* the embedded detail widget, or null while the list is up */
  c.detail = null;

  c.tabs = [
    { key: 'all',     label: c.data.t.tabAll },
    { key: 'active',  label: c.data.t.tabActive },
    { key: 'done',    label: c.data.t.tabDone },
    { key: 'stopped', label: c.data.t.tabStopped }
  ];

  function hit(p, q) {
    return (
      (p.name    || '').toLowerCase().indexOf(q) !== -1 ||
      (p.number  || '').toLowerCase().indexOf(q) !== -1 ||
      (p.program || '').toLowerCase().indexOf(q) !== -1 ||
      (p.award   || '').toLowerCase().indexOf(q) !== -1
    );
  }

  function matching() {
    var q = (c.query || '').trim().toLowerCase();

    var out = (c.data.projects || []).filter(function(p) {
      if (c.tab !== 'all' && p.group !== c.tab) return false;
      if (q && !hit(p, q)) return false;
      return true;
    });

    /* a project reporting red is the one worth reading first,
       whichever tab is open */
    out.sort(function(x, y) {
      var rank = { red: 0, amber: 1, green: 2 };
      return rank[x.health] - rank[y.health];
    });

    return out;
  }

  c.total = function() {
    var n = matching().length;
    return n === 1 ? n + ' project' : n + ' projects';
  };

  c.shown = function() { return matching(); };

  c.onChange = function() {};

  c.setTab = function(key) {
    if (c.tab === key) return;
    c.tab = key;
  };

  c.clearSearch = function() { c.query = ''; };

  c.clearAll = function() {
    c.query = '';
    c.tab = 'all';
  };


  /* =====================================================
     HANDING OFF TO THE DETAIL WIDGET

     A project has status reports, change requests, claims,
     risks and issues hanging off it. That is a page, not a
     dialog, and it has its own widget. The list loads it in
     place and steps out of the way.
     ===================================================== */

  c.openProject = function(project) {
    if (!project || !project.sysId) return;

    c.loading = project.sysId;

    spUtil.get(c.data.detailWidget, { project_id: project.sysId })
      .then(function(widget) {
        c.loading = '';
        c.detail = widget;
        /* the detail widget starts at its own top, not halfway
           down wherever the list was scrolled to */
        $window.scrollTo({ top: 0, behavior: 'smooth' });
      }, function() {
        c.loading = '';
      });
  };

  /* the detail widget emits this from its back button */
  $rootScope.$on('gn_close_project_details', function() {
    c.detail = null;
    /* a report or a claim may have been filed while it was
       open, so the counts on the list are refetched */
    c.server.update();
  });

};

sp_widget.css:
/* =========================================================
   GATENOW · MY PROJECTS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Same tokens as the other dashboard pages: navy, one accent
   blue, neutrals built from the navy at different opacities.

   THE ONE EXCEPTION
   Project health is a red, amber, green scale that the platform
   already publishes on the record, and reporting it in anything
   other than those three colours would be its own kind of lie.
   So this page carries all three, desaturated to sit inside the
   palette rather than shouting over it. They appear only where
   health is being reported, never as decoration.

   TYPE
     tile      30  700  tabular   headline figures
     title     26  700  -0.03em   page title
     name      19  600  -0.018em  project name
     percent   22  700  tabular   completion figure
     body      15  400             descriptions
     data      14  600  tabular    dates and amounts
     label     11  600   0.14em    uppercase small caps
   ========================================================= */

/* ---------- overflow overrides ---------- */

.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gn-layout { overflow: visible !important; }

/* The column holds the rail and lets it decide how wide to be.
   It used to carry a width through an inline ng-style, which is
   what put 140px of the rail on top of this page: the column
   reserved 96 while the rail draws 236.

   The transition moved to the rail, which is the element that
   actually changes width. Animating a wrapper that never
   resized was doing nothing. */

.aw-sidebar {
  flex: 0 0 auto;
  position: sticky;
  top: 0;
  height: 100vh;
  z-index: 10; /* Ensures sidebar tooltips stay above the scrolling dashboard */
  overflow: visible; /* Kept visible to prevent tooltip clipping as noted in your comments */
}



/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$r-navy:   #0a2540;
$r-ink-2:  rgba(10, 37, 64, 0.72);
$r-ink-3:  rgba(10, 37, 64, 0.54);
$r-ink-4:  rgba(10, 37, 64, 0.38);
$r-line:   rgba(10, 37, 64, 0.10);
$r-line-2: rgba(10, 37, 64, 0.06);
$r-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$r-blue:    #1560e0;
$r-blue-dk: #0f4cbb;
$r-blue-1:  rgba(21, 96, 224, 0.08);
$r-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- health, the platform's own scale ---------- */
$r-green:   #1f8a63;
$r-green-1: rgba(31, 138, 99, 0.12);
$r-amber:   #a4741f;
$r-amber-1: rgba(164, 116, 31, 0.12);
$r-red:     #b8394a;
$r-red-1:   rgba(184, 57, 74, 0.10);

$r-white: #ffffff;
$r-page:  #f4f6fb;
$r-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$r-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

.gn-layout {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: $r-page;
  font-family: $r-font;
}

/* Without min-width: 0 a flex child refuses to shrink below its
   own content width, and slides under the rail rather than
   narrowing. That is the usual cause of a stubborn overlap once
   the widths are right. */
.gpr {
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.gpr {
  min-height: 100vh;
  padding: 28px 36px 68px;
  background: $r-page;
  font-family: $r-font;
  color: $r-navy;
  -webkit-font-smoothing: antialiased;
}

.gpr *,
.gpr *::before,
.gpr *::after { box-sizing: border-box; }


/* =========================================================
   HEADER
   ========================================================= */

.gpr-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  margin-bottom: 22px;
}

.gpr-top__lead { min-width: 0; }

.gpr .gpr-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $r-navy;
}

.gpr .gpr-top__sub {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 7px 0 0;
  font-size: 13.5px;
  color: $r-ink-3;
}

.gpr-live {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: $r-green;
  box-shadow: 0 0 0 3px $r-green-1;
  flex-shrink: 0;
}

.gpr-top__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.gpr-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 330px;
  height: 42px;
  padding: 0 12px 0 14px;
  margin: 0;
  border: 1px solid $r-line;
  border-radius: 11px;
  background: $r-white;
  font-weight: 400;
  transition: border-color 0.4s $r-ease, box-shadow 0.4s $r-ease;
}

.gpr-search:focus-within {
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $r-blue-1;
}

.gpr-search__icon {
  font-size: 13px;
  color: $r-ink-4;
  flex-shrink: 0;
}

.gpr-search__field {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: $r-navy;
}

.gpr-search__field::placeholder { color: $r-ink-4; }

.gpr-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $r-tint;
  color: $r-ink-3;
  font-size: 10px;
  cursor: pointer;
  flex-shrink: 0;
}

.gpr-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: $r-blue;
  color: $r-white;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
  flex-shrink: 0;
  box-shadow: 0 6px 16px rgba(21, 96, 224, 0.28);
}


/* =========================================================
   NOTHING YET
   ========================================================= */

.gpr-blank {
  max-width: 520px;
  margin: 70px auto;
  padding: 52px 34px 46px;
  border: 1px solid $r-line;
  border-radius: 18px;
  background: $r-white;
  text-align: center;
}

.gpr-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $r-blue-1;
  color: $r-blue;
  font-size: 22px;
}

.gpr .gpr-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $r-navy;
}

.gpr .gpr-blank__text {
  max-width: 46ch;
  margin: 11px auto 24px;
  font-size: 15px;
  line-height: 1.64;
  color: $r-ink-3;
}


/* =========================================================
   TILES
   ========================================================= */

.gpr-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.gpr-tile {
  position: relative;
  padding: 20px 22px 22px;
  border: 1px solid $r-line;
  border-radius: 16px;
  background: $r-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: transform 0.5s $r-ease, box-shadow 0.5s $r-ease;
}

.gpr-tile:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(10, 37, 64, 0.08);
}

.gpr-tile__rule {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: $r-blue-2;
  transform-origin: left center;
}

.gpr-tile.is-alert .gpr-tile__rule { background: rgba(164, 116, 31, 0.34); }

.gpr .gpr-tile__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr .gpr-tile__value {
  margin: 12px 0 0;
  font-size: 30px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.034em;
  font-variant-numeric: tabular-nums;
  color: $r-navy;
}

.gpr .gpr-tile__note {
  margin: 8px 0 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: $r-ink-3;
}

.gpr-tile.is-alert .gpr-tile__note {
  color: $r-amber;
  font-weight: 500;
}


/* =========================================================
   PANELS
   ========================================================= */

.gpr-panels {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
  gap: 16px;
  margin-bottom: 22px;
}

.gpr-panel {
  padding: 22px 24px 24px;
  border: 1px solid $r-line;
  border-radius: 16px;
  background: $r-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gpr-panel__head { margin-bottom: 20px; }

.gpr .gpr-panel__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $r-navy;
}

.gpr .gpr-panel__hint {
  margin: 5px 0 0;
  font-size: 12.5px;
  color: $r-ink-4;
}

.gpr .gpr-panel__empty {
  margin: 0;
  padding: 22px 0 4px;
  font-size: 13.5px;
  color: $r-ink-4;
}


/* ---------- what needs attention ----------

   The split bar and its three-count legend are gone. At one
   project the bar was a full width green block with a 1 in it,
   and the legend underneath repeated the same thing in words.

   What replaces it names the projects that are wrong and why,
   and says so plainly when none are. Colour appears only on the
   reasons, never as a background wash, so a page with two
   amber projects looks different from a page with none without
   either looking like an alarm.
   ------------------------------------------------------- */

.gpr .gpr-attn {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gpr-attn__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  width: 100%;
  padding: 12px 12px 12px 14px;
  border: 0;
  border-left: 3px solid transparent;
  border-radius: 0 10px 10px 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: background 0.35s $r-ease;
}

.gpr-attn__row:hover { background: $r-tint; }

.gpr-attn__row:focus-visible {
  outline: 2px solid $r-blue;
  outline-offset: -2px;
}

/* the rail carries the health, so the row is identifiable
   before any of the reasons are read */
.gpr-attn--red .gpr-attn__row   { border-left-color: $r-red; }
.gpr-attn--amber .gpr-attn__row { border-left-color: $r-amber; }
.gpr-attn--green .gpr-attn__row { border-left-color: $r-blue; }

.gpr-attn__name {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $r-navy;
}

.gpr-attn__why {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.gpr-tag {
  padding: 4px 10px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.gpr-tag--red   { background: rgba(184, 57, 74, 0.1);  color: $r-red; }
.gpr-tag--amber { background: rgba(164, 116, 31, 0.12); color: $r-amber; }
.gpr-tag--blue  { background: $r-blue-1;                color: $r-blue-dk; }


/* ---------- nothing needs attention ----------
   A sentence, because that is what the answer is.
   ------------------------------------------------------- */

.gpr-clear {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 4px 8px;
}

.gpr-clear__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  border-radius: 50%;
  background: rgba(31, 138, 99, 0.1);
  color: $r-green;
  font-size: 15px;
}

.gpr-clear__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.gpr-clear__title {
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: -0.014em;
  color: $r-navy;
}

.gpr-clear__text {
  font-size: 13px;
  color: $r-ink-3;
}

.gpr-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba(164, 116, 31, 0.12);
  color: $r-amber;
  font-size: 12.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}


/* ---------- the delivery gap ----------

   A row of percent complete bars answered one question and hid
   a better one. This plots two points per project on the same
   track, schedule elapsed and work complete, and the connector
   between them is the finding.

   Reading rules:
     hollow ring   how much of the schedule has gone
     solid dot     how much of the work is done
     the bar       the distance between the two

   Colour lives on the connector only. The markers stay neutral,
   so the eye compares lengths rather than hues, and a portfolio
   with three late projects looks different from one with none
   without any row shouting on its own.
   ------------------------------------------------------- */

$gap-pad: 152px;
$gap-val: 48px;

.gpr-gap { min-width: 0; }

.gpr-gap__scale {
  display: grid;
  grid-template-columns: $gap-pad minmax(0, 1fr) $gap-val;
  gap: 14px;
  margin-bottom: 10px;
}

.gpr-gap__ticks {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: $r-ink-4;
}

.gpr-gap__pad { min-width: 0; }

.gpr-gap__row {
  display: grid;
  grid-template-columns: $gap-pad minmax(0, 1fr) $gap-val;
  align-items: center;
  gap: 14px;
  padding: 7px 0;
}

.gpr-gap__name {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.gpr-gap__label {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: -0.012em;
  color: $r-navy;
  transition: color 0.35s $r-ease;
}

.gpr-gap__name:hover .gpr-gap__label { color: $r-blue-dk; }

.gpr-gap__name:focus-visible {
  outline: 2px solid $r-blue;
  outline-offset: 2px;
  border-radius: 6px;
}

.gpr-gap__phase {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr-gap__track {
  position: relative;
  display: block;
  height: 20px;
}

/* three hairlines rather than a grid, because two of them are
   only there to stop 50 percent being a guess */
.gpr-gap__grid {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 1px;
  background: $r-line-2;
}

.gpr-gap__grid--mid { left: 50%; }
.gpr-gap__grid--end { left: auto; right: 0; }

/* the connector carries the whole message, so it carries the
   colour */
.gpr-gap__link {
  position: absolute;
  top: 50%;
  height: 5px;
  margin-top: -2.5px;
  border-radius: 999px;
  background: rgba(10, 37, 64, 0.18);
  transform-origin: left center;
}

.gpr-gap__row--even .gpr-gap__link  { background: rgba(21, 96, 224, 0.32); }
.gpr-gap__row--ahead .gpr-gap__link { background: rgba(31, 138, 99, 0.42); }
.gpr-gap__row--watch .gpr-gap__link { background: $r-amber; }
.gpr-gap__row--late .gpr-gap__link  { background: $r-red; }

/* time gone: a ring, because it is a position rather than an
   achievement */
.gpr-gap__time {
  position: absolute;
  top: 50%;
  width: 13px;
  height: 13px;
  margin: -6.5px 0 0 -6.5px;
  border-radius: 50%;
  background: $r-white;
  box-shadow: inset 0 0 0 2px rgba(10, 37, 64, 0.42);
  z-index: 2;
}

/* work done: solid, because it is the thing that was actually
   delivered */
.gpr-gap__done {
  position: absolute;
  top: 50%;
  width: 13px;
  height: 13px;
  margin: -6.5px 0 0 -6.5px;
  border-radius: 50%;
  background: $r-navy;
  border: 2px solid $r-white;
  z-index: 3;
}

.gpr-gap__row--late .gpr-gap__done  { background: $r-red; }
.gpr-gap__row--watch .gpr-gap__done { background: $r-amber; }
.gpr-gap__row--ahead .gpr-gap__done { background: $r-green; }

.gpr-gap__value {
  text-align: right;
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $r-ink-4;
}

.gpr-gap__row--late .gpr-gap__value  { color: $r-red; }
.gpr-gap__row--watch .gpr-gap__value { color: $r-amber; }
.gpr-gap__row--ahead .gpr-gap__value { color: $r-green; }

.gpr .gpr-gap__verdict {
  margin: 16px 0 0;
  padding-top: 14px;
  border-top: 1px solid $r-line-2;
  font-size: 13px;
  font-weight: 500;
  color: $r-ink-3;
}

.gpr .gpr-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gpr .gpr-legend li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: $r-ink-3;
}

.gpr-legend__time {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: $r-white;
  box-shadow: inset 0 0 0 2px rgba(10, 37, 64, 0.42);
  flex-shrink: 0;
}

.gpr-legend__done {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: $r-navy;
  flex-shrink: 0;
}

/* projects that cannot be plotted are named rather than drawn
   at a position the data does not support */
.gpr-nodate {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid $r-line-2;
}

.gpr-nodate__label {
  display: block;
  margin-bottom: 8px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr .gpr-nodate__list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gpr .gpr-nodate__list li {
  padding: 5px 11px;
  border-radius: 8px;
  background: $r-tint;
  font-size: 12.5px;
  color: $r-ink-3;
}

.gpr .gpr-nodate__list strong {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $r-navy;
}


/* =========================================================
   TABS
   ========================================================= */

.gpr-filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 20px;
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid $r-line;
}

.gpr-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.gpr-tab {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: $r-ink-2;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.4s $r-ease, border-color 0.4s $r-ease, color 0.4s $r-ease;
}

.gpr-tab:hover {
  background: rgba(255, 255, 255, 0.7);
  color: $r-navy;
}

.gpr-tab.is-on {
  background: $r-white;
  border-color: $r-line;
  color: $r-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.05);
}

.gpr-tab__count {
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: $r-ink-4;
}

.gpr .gpr-range {
  margin: 0;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $r-ink-4;
}


/* =========================================================
   PROJECT CARD
   ========================================================= */

.gpr-list {
  display: grid;
  gap: 14px;
}

.gpr-card {
  position: relative;
  padding: 22px 26px 20px 28px;
  border: 1px solid $r-line;
  border-radius: 16px;
  background: $r-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: border-color 0.5s $r-ease, box-shadow 0.5s $r-ease;
}

.gpr-card:hover {
  border-color: $r-blue-2;
  box-shadow: 0 14px 34px rgba(10, 37, 64, 0.08);
}

.gpr-card__rail {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
}

.gpr-card--green .gpr-card__rail { background: $r-green; }
.gpr-card--amber .gpr-card__rail { background: $r-amber; }
.gpr-card--red .gpr-card__rail   { background: $r-red; }

/* a project reporting red is the one worth reading first */
.gpr-card--red { background: linear-gradient(180deg, rgba(184, 57, 74, 0.035) 0%, $r-white 42%); }

.gpr-card__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 110px;
  gap: 24px;
  align-items: start;
  margin-bottom: 16px;
}

.gpr-card__lead { min-width: 0; }

.gpr-card__top {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 10px;
}

.gpr-health {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.gpr-health__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gpr-health--green { color: $r-green; }
.gpr-health--amber { color: $r-amber; }
.gpr-health--red   { color: $r-red; }

.gpr-health--green .gpr-health__dot { background: $r-green; }
.gpr-health--amber .gpr-health__dot { background: $r-amber; }
.gpr-health--red .gpr-health__dot   { background: $r-red; }

.gpr-card__meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr-card__sep { color: rgba(10, 37, 64, 0.22); }

.gpr-due {
  padding: 3px 9px;
  border: 1px solid $r-line;
  border-radius: 6px;
  background: $r-tint;
  color: $r-ink-3;
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* past its planned end date, which is worth saying out loud */
.gpr-due.is-late {
  border-color: rgba(184, 57, 74, 0.28);
  background: $r-red-1;
  color: $r-red;
}

.gpr .gpr-card__name {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.018em;
  color: $r-navy;
}

.gpr .gpr-card__desc {
  max-width: 72ch;
  margin: 6px 0 0;
  font-size: 15px;
  line-height: 1.55;
  color: $r-ink-3;
}

.gpr-card__figure {
  text-align: right;
  min-width: 0;
}

.gpr-figure__value {
  display: block;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: $r-navy;
}

.gpr-figure__label {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr-card__track {
  display: block;
  height: 6px;
  margin-bottom: 18px;
  border-radius: 999px;
  background: $r-tint;
  overflow: hidden;
}

.gpr-card__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  transform-origin: left center;
}

.gpr-card__fill--green { background: $r-blue; }
.gpr-card__fill--amber { background: $r-amber; }
.gpr-card__fill--red   { background: $r-red; }


/* ---------- phase track ---------- */

.gpr-phase {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 18px;
}

.gpr-phase__step { min-width: 0; }

.gpr-phase__bar {
  display: block;
  height: 4px;
  border-radius: 999px;
  background: $r-line-2;
  transform-origin: left center;
}

.gpr-phase__name {
  display: block;
  margin-top: 7px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr-phase__step.is-done .gpr-phase__bar { background: rgba(21, 96, 224, 0.35); }
.gpr-phase__step.is-done .gpr-phase__name { color: $r-ink-3; }

.gpr-phase__step.is-now .gpr-phase__bar { background: $r-blue; }

.gpr-phase__step.is-now .gpr-phase__name {
  color: $r-blue-dk;
  font-weight: 700;
}

/* cancelled did not reach the last phase, it stopped */
.gpr-phase.is-stopped .gpr-phase__bar { background: rgba(10, 37, 64, 0.14); }
.gpr-phase.is-stopped .gpr-phase__name { color: $r-ink-4; }


/* ---------- foot ---------- */

.gpr-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px 24px;
  padding-top: 16px;
  border-top: 1px solid $r-line-2;
}

.gpr .gpr-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 28px;
  margin: 0;
  padding: 0;
}

.gpr-fact {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.gpr .gpr-fact dt {
  margin: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $r-ink-4;
}

.gpr .gpr-fact dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  color: $r-navy;
}

.gpr .gpr-fact dd.is-blank {
  font-weight: 400;
  font-style: italic;
  color: $r-ink-4;
}

.gpr-card__right {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.gpr .gpr-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gpr .gpr-counts li {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  padding: 5px 11px;
  border-radius: 8px;
  background: $r-tint;
  font-size: 12px;
  color: $r-ink-3;
  white-space: nowrap;
}

.gpr-counts__n {
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $r-navy;
}

/* a count of zero is still worth showing, but not worth
   drawing the eye to */
.gpr .gpr-counts li.is-zero { opacity: 0.5; }
.gpr .gpr-counts li.is-zero .gpr-counts__n { color: $r-ink-4; }


/* =========================================================
   BUTTONS
   ========================================================= */

.gpr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $r-ease, border-color 0.4s $r-ease, color 0.4s $r-ease;
}

.gpr-btn--primary {
  background: $r-blue;
  border-color: $r-blue;
  color: $r-white;
}

.gpr-btn--primary:hover,
.gpr-btn--primary:focus {
  background: $r-blue-dk;
  border-color: $r-blue-dk;
  color: $r-white;
  text-decoration: none;
}

.gpr-btn--ghost {
  border-color: $r-line;
  color: $r-ink-2;
}

.gpr-btn--ghost:hover,
.gpr-btn--ghost:focus {
  border-color: $r-blue-2;
  color: $r-blue-dk;
  text-decoration: none;
}

.gpr-btn:focus-visible,
.gpr-tab:focus-visible,
.gpr-mtab:focus-visible,
.gpr-search__clear:focus-visible {
  outline: 2px solid $r-blue;
  outline-offset: 2px;
}


/* =========================================================
   NO MATCH
   ========================================================= */

.gpr-nomatch {
  padding: 62px 24px;
  border: 1px dashed $r-line;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.6);
  text-align: center;
}

.gpr .gpr-nomatch__title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: $r-navy;
}

.gpr .gpr-nomatch__text {
  max-width: 44ch;
  margin: 9px auto 18px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $r-ink-3;
}


/* =========================================================
   THE DETAIL SLOT

   The modal that used to live here is gone. A project carries
   status reports, change requests, claims, risks and issues,
   and that is a page rather than a dialog: a dialog would have
   put a scrollbar inside a scrollbar and lost the browser back
   button.

   The embedded widget brings its own layout, so this only gives
   it the column.
   ========================================================= */

.gpr-detail {
  min-width: 0;
}

/* the card is clickable, so it says so */
.gpr-card {
  cursor: pointer;
}

.gpr-card:focus-visible {
  outline: 2px solid $r-blue;
  outline-offset: 2px;
}

/* while the detail widget loads, the card it came from holds
   still rather than pretending nothing was pressed */
.gpr-card.is-busy {
  border-color: $r-blue-2;
  box-shadow: 0 14px 34px rgba(10, 37, 64, 0.08);
}

.gpr-card.is-busy .gpr-card__name { color: $r-blue-dk; }


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gprRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gprDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  .gpr-top  { animation: gprRise 0.6s $r-ease backwards; }
  .gpr-tile { animation: gprRise 0.62s $r-ease backwards; }

  .gpr-tile--active   { animation-delay: 0.06s; }
  .gpr-tile--progress { animation-delay: 0.12s; }
  .gpr-tile--open     { animation-delay: 0.18s; }
  .gpr-tile--paid     { animation-delay: 0.24s; }

  .gpr-tile__rule { animation: gprDrawX 0.7s $r-ease 0.3s backwards; }

  .gpr-panel { animation: gprRise 0.62s $r-ease 0.28s backwards; }

  /* the connectors draw out from their left edge, so the gap
     appears rather than arriving */
  .gpr-gap__link { animation: gprDrawX 0.7s $r-ease backwards; }

  .gpr-gap__row--n1 .gpr-gap__link { animation-delay: 0.40s; }
  .gpr-gap__row--n2 .gpr-gap__link { animation-delay: 0.45s; }
  .gpr-gap__row--n3 .gpr-gap__link { animation-delay: 0.50s; }
  .gpr-gap__row--n4 .gpr-gap__link { animation-delay: 0.55s; }
  .gpr-gap__row--n5 .gpr-gap__link { animation-delay: 0.60s; }
  .gpr-gap__row--n6 .gpr-gap__link { animation-delay: 0.65s; }
  .gpr-gap__row--n7 .gpr-gap__link { animation-delay: 0.70s; }
  .gpr-gap__row--n8 .gpr-gap__link { animation-delay: 0.75s; }

  .gpr-filters { animation: gprRise 0.6s $r-ease 0.34s backwards; }

  /* replays on every tab change, because ng-repeat rebuilds its
     nodes and the keyframe starts again with them */
  .gpr-card { animation: gprRise 0.5s $r-ease backwards; }

  .gpr-card--n1  { animation-delay: 0.02s; }
  .gpr-card--n2  { animation-delay: 0.05s; }
  .gpr-card--n3  { animation-delay: 0.08s; }
  .gpr-card--n4  { animation-delay: 0.11s; }
  .gpr-card--n5  { animation-delay: 0.14s; }
  .gpr-card--n6  { animation-delay: 0.17s; }
  .gpr-card--n7  { animation-delay: 0.20s; }
  .gpr-card--n8  { animation-delay: 0.23s; }
  .gpr-card--n9  { animation-delay: 0.26s; }
  .gpr-card--n10 { animation-delay: 0.29s; }

  .gpr-card__fill  { animation: gprDrawX 0.7s $r-ease 0.1s backwards; }
  .gpr-phase__bar  { animation: gprDrawX 0.5s $r-ease 0.16s backwards; }

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1280px) {

  .gpr { padding: 26px 24px 60px; }

  .gpr-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .gpr-panels { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 900px) {

  .gpr { padding: 22px 16px 52px; }

  .gpr-top__right {
    width: 100%;
    order: 2;
  }

  .gpr-search { width: 100%; }

  .gpr-tiles { grid-template-columns: minmax(0, 1fr); }

  .gpr-tabs {
    flex-wrap: nowrap;
    width: 100%;
    overflow-x: auto;
    padding-bottom: 3px;
    -webkit-overflow-scrolling: touch;
  }

  .gpr-tab { flex-shrink: 0; }

  .gpr-card__head {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .gpr-card__figure {
    display: flex;
    align-items: baseline;
    gap: 8px;
    text-align: left;
  }

  .gpr-figure__label { margin-top: 0; }

  /* five phase labels do not fit across a phone, so only the
     current one keeps its name */
  .gpr-phase { gap: 5px; }

  .gpr-phase__name { display: none; }

  .gpr-phase__step.is-now .gpr-phase__name {
    display: block;
    white-space: nowrap;
  }

  .gpr-card__foot {
    align-items: flex-start;
    flex-direction: column;
  }

  /* the reasons drop under the name rather than being squeezed
     into a column that cannot hold two of them */
  .gpr-attn__row {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }

  .gpr-attn__why { justify-content: flex-start; }

  /* the name column narrows first, then the value column goes,
     because the two markers are the part that has to stay
     readable */
  .gpr-gap__scale,
  .gpr-gap__row {
    grid-template-columns: 104px minmax(0, 1fr) 36px;
    gap: 10px;
  }

  .gpr-gap__phase { display: none; }

  .gpr-card__right {
    width: 100%;
    justify-content: space-between;
  }

  .gpr-rag { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .gpr .gpr-kvs { grid-template-columns: minmax(0, 1fr); }

}

@media (prefers-reduced-motion: reduce) {
  .gpr * { transition: none; }
  .gpr-tile:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · MY PROJECTS
     Service Portal widget · Server script

     Scoped to the projects belonging to the signed in
     applicant, with the related records the applicant actually
     needs: status reports, change requests, reimbursements,
     risks and issues.

     Audit history and audit records are deliberately not read.
     They are an administrative trail, not something an
     applicant has any use for, and pulling them would double
     the query count for nothing.

     Field names are taken from the project form: project_name,
     program_manager, status, phase, percent_complete,
     description, award, applicant, program, and the four dates.

     GlideRecordSecure throughout.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';
  var PROJECT   = 'x_enno_gatenow_project';
  var REPORT    = 'x_enno_gatenow_status_report';
  var CHANGE    = 'x_enno_gatenow_change_request';
  var CLAIM     = 'x_enno_gatenow_reimbursement';

  /* The risk and issue table names are not on any screenshot, so
     each candidate is tested with isValid before it is used and
     skipped quietly if it is not there. Add the real name to the
     front of either list when you know it. */
  var RISK_TABLES  = ['x_enno_gatenow_risk', 'x_enno_gatenow_project_risk'];
  var ISSUE_TABLES = ['x_enno_gatenow_issue', 'x_enno_gatenow_project_issue'];

  var me = gs.getUserID();

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }

  function lower(v) {
    return (v === null || v === undefined) ? '' : ('' + v).toLowerCase();
  }

  function toGDT(value) {
    if (!value) return null;
    var s = '' + value;
    if (s.length === 10) s += ' 00:00:00';
    try { return new GlideDateTime(s); } catch (e) { return null; }
  }

  function fmtDate(value) {
    var g = toGDT(value);
    if (!g) return '';
    try { return g.getDate().getByFormat('d MMM yyyy'); } catch (e) { return '' + value; }
  }

  function daysUntil(value) {
    var g = toGDT(value);
    if (!g) return null;
    try {
      var ms = GlideDateTime.subtract(new GlideDateTime(), g).getNumericValue();
      return Math.round(ms / 86400000);
    } catch (e) { return null; }
  }

  function num(raw) {
    if (raw === null || raw === undefined || raw === '') return 0;
    var s = '' + raw;
    if (s.indexOf(';') !== -1) s = s.split(';').pop();
    var n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }

  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function fmtFull(n)  { return n > 0 ? '$' + commas(n) : ''; }

  function fmtShort(n) {
    if (!n) return '$0';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }

  /* the long fields on these records are HTML areas, and the
     screenshots show raw <p> tags leaking into the list view */
  function text(raw, cap) {
    if (!raw) return '';
    var s = ('' + raw)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    if (cap && s.length > cap) s = s.substring(0, cap).replace(/\s+\S*$/, '') + '...';
    return s;
  }

  function firstValidTable(list) {
    for (var i = 0; i < list.length; i++) {
      try {
        var probe = new GlideRecordSecure(list[i]);
        if (probe.isValid()) return list[i];
      } catch (e) { /* next */ }
    }
    return '';
  }


  /* ---------- chrome ---------- */
  data.sideBar = $sp.getWidget(opt('sidebar_widget', 'sidebar'));

  var u = gs.getUser();
  var fn = u.getFirstName() || '';
  var ln = u.getLastName() || '';
  data.userInitials = (fn.charAt(0) + ln.charAt(0)).toUpperCase() ||
                      (u.getDisplayName() || 'U').substring(0, 2).toUpperCase();


  /* ============================================================
     PHASE AND HEALTH
     ============================================================ */

  /* Cancelled sits outside the run rather than at the end of it,
     because a cancelled project did not reach the last phase, it
     stopped. */
  var PHASES = ['initiating', 'planning', 'executing', 'delivering', 'closed complete'];

  data.phaseTrack = [
    gs.getMessage('Initiating'),
    gs.getMessage('Planning'),
    gs.getMessage('Executing'),
    gs.getMessage('Delivering'),
    gs.getMessage('Closed')
  ];

  function phaseIndex(label) {
    var v = lower(label);
    if (v.indexOf('cancel') !== -1) return -1;
    for (var i = 0; i < PHASES.length; i++) {
      if (v.indexOf(PHASES[i]) !== -1) return i;
    }
    if (v.indexOf('closed') !== -1) return 4;
    return 0;
  }

  function healthOf(label) {
    var v = lower(label);
    if (v.indexOf('red') !== -1)    return { key: 'red',    label: gs.getMessage('Critical') };
    if (v.indexOf('yellow') !== -1) return { key: 'amber',  label: gs.getMessage('At risk') };
    return { key: 'green', label: gs.getMessage('On track') };
  }


  /* ============================================================
     WHICH PROJECTS
     ============================================================ */

  var applicantIds = [];

  try {
    var ap = new GlideRecordSecure(APPLICANT);
    ap.addQuery('user', me);
    ap.query();
    while (ap.next()) applicantIds.push(ap.getUniqueValue());
  } catch (e) {
    gs.error('[MyProjects] applicant lookup: ' + e.message);
  }

  data.projects = [];

  var counts = { all: 0, active: 0, done: 0, stopped: 0 };
  var health = { green: 0, amber: 0, red: 0 };
  var progressSum = 0;
  var claimedPaid = 0;
  var openActions = 0;

  var riskTable  = firstValidTable(RISK_TABLES);
  var issueTable = firstValidTable(ISSUE_TABLES);

  data.hasRisks  = !!riskTable;
  data.hasIssues = !!issueTable;

  /* one small helper so the five related lists read the same */
  function relatedList(table, projectId, limit, mapper) {
    var out = [];
    if (!table) return out;
    try {
      var gr = new GlideRecordSecure(table);
      gr.addQuery('project', projectId);
      gr.orderByDesc('sys_created_on');
      gr.setLimit(limit);
      gr.query();
      while (gr.next()) out.push(mapper(gr));
    } catch (e) {
      gs.info('[MyProjects] ' + table + ' unavailable: ' + e.message);
    }
    return out;
  }

  try {

    if (applicantIds.length) {

      var pj = new GlideRecordSecure(PROJECT);
      pj.addQuery('applicant', 'IN', applicantIds.join(','));
      pj.orderByDesc('sys_updated_on');
      pj.setLimit(50);
      pj.query();

      while (pj.next()) {

        var projectId = pj.getUniqueValue();
        var phaseLabel = pj.getDisplayValue('phase') || '';
        var pIndex = phaseIndex(phaseLabel);
        var h = healthOf(pj.getDisplayValue('status'));

        var group;
        if (pIndex === -1) group = 'stopped';
        else if (pIndex >= 4) group = 'done';
        else group = 'active';

        var pct = parseInt(pj.getValue('percent_complete') || 0, 10);
        if (isNaN(pct)) pct = 0;

        /* ---- status reports ---- */
        var reports = relatedList(REPORT, projectId, 6, function (gr) {
          return {
            number : gr.getValue('number'),
            date   : fmtDate(pick(gr, ['status_date', 'sys_created_on'])),
            type   : gr.getDisplayValue('report_status'),
            pct    : parseInt(gr.getValue('percent_complete') || 0, 10) || 0,
            health : healthOf(gr.getDisplayValue('overall_health')),
            schedule: healthOf(gr.getDisplayValue('schedule')),
            cost    : healthOf(gr.getDisplayValue('cost')),
            resource: healthOf(gr.getDisplayValue('resources')),
            scope   : healthOf(gr.getDisplayValue('scope')),
            summary : text(gr.getValue('executive_summary'), 600),
            achieved: text(gr.getValue('achievements_last_month'), 400),
            nextUp  : text(gr.getValue('key_activities_next_month'), 400)
          };
        });

        /* ---- change requests ---- */
        var changes = relatedList(CHANGE, projectId, 10, function (gr) {
          var ap = lower(gr.getValue('approval'));
          return {
            number  : gr.getValue('number'),
            title   : pick(gr, ['title', 'short_description']),
            category: gr.getDisplayValue('category'),
            priority: gr.getDisplayValue('priority'),
            impact  : gr.getDisplayValue('impact'),
            approval: gr.getDisplayValue('approval'),
            state   : ap.indexOf('approved') !== -1 ? 'good'
                    : ap.indexOf('rejected') !== -1 ? 'bad'
                    : 'wait',
            reason  : text(gr.getValue('reason_for_change'), 300),
            proposed: text(gr.getValue('proposed_change'), 300),
            created : fmtDate(gr.getValue('sys_created_on'))
          };
        });

        /* ---- reimbursements ---- */
        var claims = relatedList(CLAIM, projectId, 10, function (gr) {
          var st = lower(gr.getDisplayValue('status'));
          var amount = num(pick(gr, ['amount_requested', 'federal_share_now_requested', 'total']));
          return {
            number : gr.getValue('number'),
            status : gr.getDisplayValue('status'),
            state  : st.indexOf('paid') !== -1     ? 'good'
                   : st.indexOf('rejected') !== -1 ? 'bad'
                   : st.indexOf('approved') !== -1 ? 'ok'
                   : 'wait',
            amount : amount,
            amountText: fmtFull(amount),
            summary: pick(gr, ['short_description']),
            created: fmtDate(gr.getValue('sys_created_on'))
          };
        });

        /* ---- risks and issues ---- */
        function riskish(gr) {
          return {
            number  : gr.getValue('number'),
            title   : pick(gr, ['short_description', 'title', 'description']),
            state   : gr.getDisplayValue('state') || gr.getDisplayValue('status'),
            priority: gr.getDisplayValue('priority') || gr.getDisplayValue('impact'),
            created : fmtDate(gr.getValue('sys_created_on'))
          };
        }

        var risks  = relatedList(riskTable, projectId, 10, riskish);
        var issues = relatedList(issueTable, projectId, 10, riskish);

        /* anything sitting on an approval or a payment is an open
           thread the applicant may need to chase */
        var waiting = 0;
        for (var ci = 0; ci < changes.length; ci++) if (changes[ci].state === 'wait') waiting++;
        for (var li = 0; li < claims.length; li++)  if (claims[li].state === 'wait' || claims[li].state === 'ok') waiting++;

        var paid = 0;
        for (var pi = 0; pi < claims.length; pi++) {
          if (claims[pi].state === 'good') paid += claims[pi].amount;
        }

        /* "1 days left" was the template doing arithmetic and
           then concatenating a plural. The sentence is built
           here where the number is known. */
        var toEnd = daysUntil(pj.getValue('planned_end_date'));
        var dueLabel = '';

        if (group === 'active' && toEnd !== null) {
          if (toEnd < 0) {
            var over = Math.abs(toEnd);
            dueLabel = over + ' ' + (over === 1 ? gs.getMessage('day overdue')
                                                : gs.getMessage('days overdue'));
          } else if (toEnd === 0) {
            dueLabel = gs.getMessage('due today');
          } else {
            dueLabel = toEnd + ' ' + (toEnd === 1 ? gs.getMessage('day left')
                                                  : gs.getMessage('days left'));
          }
        }

        data.projects.push({
          sysId    : projectId,
          number   : pj.getValue('number'),
          name     : pick(pj, ['project_name', 'short_description']) || pj.getValue('number'),
          program  : pj.getDisplayValue('program'),
          award    : pj.getDisplayValue('award'),
          applicant: pj.getDisplayValue('applicant'),
          manager  : pj.getDisplayValue('program_manager'),
          description: text(pj.getValue('description'), 400),
          notes    : text(pick(pj, ['notes', 'work_notes']), 600),

          phase     : phaseLabel,
          phaseIndex: pIndex,
          group     : group,
          health    : h.key,
          healthLabel: h.label,
          percent   : pct,

          actualStart : fmtDate(pj.getValue('actual_start_date')),
          plannedStart: fmtDate(pj.getValue('planned_start_date')),
          actualEnd   : fmtDate(pj.getValue('actual_end_date')),
          plannedEnd  : fmtDate(pj.getValue('planned_end_date')),

          /* kept raw as well, because the delivery gap needs to
             do arithmetic on them rather than read them */
          actualStartRaw : pj.getValue('actual_start_date'),
          plannedStartRaw: pj.getValue('planned_start_date'),
          actualEndRaw   : pj.getValue('actual_end_date'),
          plannedEndRaw  : pj.getValue('planned_end_date'),
          daysToEnd   : toEnd,
          dueLabel    : dueLabel,
          late        : (group === 'active' && toEnd !== null && toEnd < 0),

          reports : reports,
          changes : changes,
          claims  : claims,
          risks   : risks,
          issues  : issues,

          counts: {
            reports: reports.length,
            changes: changes.length,
            claims : claims.length,
            risks  : risks.length,
            issues : issues.length
          },

          waiting  : waiting,
          paidText : fmtFull(paid),
          latest   : reports.length ? reports[0] : null
        });

        counts.all++;
        counts[group]++;
        health[h.key]++;
        progressSum += pct;
        claimedPaid += paid;
        openActions += waiting;
      }
    }

  } catch (e) {
    gs.error('[MyProjects] ' + e.message);
  }

  data.counts = counts;


  /* ---------- header line ---------- */
  data.headline = counts.all + ' ' +
    (counts.all === 1 ? gs.getMessage('project') : gs.getMessage('projects')) +
    '  ·  ' + counts.active + ' ' + gs.getMessage('in delivery');


  /* ---------- tiles ---------- */
  var avgPct = counts.all ? Math.round(progressSum / counts.all) : 0;

  data.tiles = [
    {
      key  : 'active',
      label: gs.getMessage('In delivery'),
      value: '' + counts.active,
      note : counts.done + ' ' + gs.getMessage('closed') +
             (counts.stopped ? ', ' + counts.stopped + ' ' + gs.getMessage('cancelled') : '')
    },
    {
      key  : 'progress',
      label: gs.getMessage('Average completion'),
      value: avgPct + '%',
      note : gs.getMessage('across every project you hold')
    },
    {
      key  : 'open',
      label: gs.getMessage('Waiting on a decision'),
      value: '' + openActions,
      /* changes awaiting approval and claims not yet paid are
         the two things that actually stall delivery */
      note : gs.getMessage('change requests and claims in flight'),
      alert: openActions > 0
    },
    {
      key  : 'paid',
      label: gs.getMessage('Reimbursed to date'),
      value: fmtShort(claimedPaid),
      note : gs.getMessage('claims marked paid')
    }
  ];


  /* ---------- what needs attention ----------

     The health split bar is gone. With one project it rendered
     a full width green block with a 1 in it, and the three
     counts sat underneath it saying the same thing in words. A
     lot of ink for one number, twice.

     What a portfolio view is actually for is answering "is
     anything wrong". So it names the projects that are, and why,
     and says so plainly when none are. That reads correctly at
     one project and stays useful at thirty.
     ------------------------------------------------------- */

  data.attention = [];

  for (var ai = 0; ai < data.projects.length; ai++) {

    var proj = data.projects[ai];
    if (proj.group !== 'active') continue;

    var why = [];

    if (proj.health === 'red') {
      why.push({ tone: 'red', text: gs.getMessage('Reported critical') });
    } else if (proj.health === 'amber') {
      why.push({ tone: 'amber', text: gs.getMessage('Reported at risk') });
    }

    if (proj.late) {
      why.push({ tone: 'red', text: proj.dueLabel });
    }

    /* Never reported, or not for a long time. A project in
       delivery that has gone quiet is the thing this page most
       needs to surface, and health alone cannot show it because
       an old green report still reads as green. */
    if (!proj.reports.length) {
      why.push({ tone: 'amber', text: gs.getMessage('No report filed yet') });
    } else {
      var sinceDays = daysUntil(proj.reports[0].rawDate);
      if (sinceDays !== null && sinceDays < -45) {
        why.push({
          tone: 'amber',
          text: Math.abs(sinceDays) + ' ' + gs.getMessage('days since the last report')
        });
      }
    }

    if (proj.waiting > 0) {
      why.push({
        tone: 'blue',
        text: proj.waiting + ' ' +
              (proj.waiting === 1 ? gs.getMessage('item awaiting a decision')
                                  : gs.getMessage('items awaiting a decision'))
      });
    }

    if (why.length) {
      data.attention.push({
        sysId : proj.sysId,
        name  : proj.name,
        number: proj.number,
        health: proj.health,
        why   : why
      });
    }
  }

  /* worst first, so the top of the list is the one to open */
  var TONE_RANK = { red: 0, amber: 1, blue: 2 };

  data.attention.sort(function (a, b) {
    return TONE_RANK[a.why[0].tone] - TONE_RANK[b.why[0].tone];
  });

  data.attentionCount = data.attention.length;

  data.attentionClear = counts.active === 0
    ? gs.getMessage('Nothing in delivery right now.')
    : (counts.active === 1
        ? gs.getMessage('Your project is on track, in date and reporting.')
        : counts.active + ' ' + gs.getMessage('projects, all on track, in date and reporting.'));

  /* ---------- the delivery gap ----------

     A row of percent complete bars answers "how far along is
     each project" and nothing else. Twenty percent is fine in
     month one and alarming in month eleven, and a bar cannot
     tell you which you are looking at.

     This plots two points per project on the same track: how
     much of the schedule has gone, and how much of the work is
     done. The distance between them is the answer, and it reads
     across the whole portfolio at a glance.

     Projects with no dates cannot be plotted, so they are named
     underneath rather than drawn at a position the data does not
     support.
     ------------------------------------------------------- */

  data.gapRows = [];
  data.gapNoDates = [];

  for (var gi2 = 0; gi2 < data.projects.length; gi2++) {

    var gp = data.projects[gi2];

    /* a cancelled project has no schedule left to be behind */
    if (gp.group === 'stopped') continue;

    var startRaw = gp.actualStartRaw || gp.plannedStartRaw;
    var endRaw   = gp.plannedEndRaw || gp.actualEndRaw;

    if (!startRaw || !endRaw) {
      data.gapNoDates.push({ sysId: gp.sysId, name: gp.name, pct: gp.percent });
      continue;
    }

    var span = daysUntil(endRaw) - daysUntil(startRaw);
    if (!span || span <= 0) {
      data.gapNoDates.push({ sysId: gp.sysId, name: gp.name, pct: gp.percent });
      continue;
    }

    var gone = 0 - daysUntil(startRaw);
    var elapsed = Math.max(0, Math.min(100, Math.round((gone / span) * 100)));
    var done = gp.percent;
    var gapPts = done - elapsed;

    /* Closed projects are shown at their real numbers rather
       than forced to 100, because a project closed at sixty
       percent is a fact worth seeing. */
    var tone;
    if (gapPts <= -20)     tone = 'late';
    else if (gapPts <= -8) tone = 'watch';
    else if (gapPts >= 8)  tone = 'ahead';
    else                   tone = 'even';

    data.gapRows.push({
      sysId  : gp.sysId,
      name   : gp.name,
      phase  : gp.phase,
      group  : gp.group,
      elapsed: elapsed,
      done   : done,
      /* the connector runs between the two markers whichever
         way round they are */
      from   : Math.min(elapsed, done),
      width  : Math.abs(gapPts),
      gap    : gapPts,
      gapText: (gapPts > 0 ? '+' : '') + gapPts,
      tone   : tone
    });
  }

  /* furthest behind first, because that is the row worth
     opening */
  data.gapRows.sort(function (a, b) { return a.gap - b.gap; });

  data.hasGap = data.gapRows.length > 0;

  var behind = 0;
  for (var bi = 0; bi < data.gapRows.length; bi++) {
    if (data.gapRows[bi].gap <= -8) behind++;
  }

  data.gapVerdict = !data.gapRows.length
    ? ''
    : (behind === 0
        ? gs.getMessage('Every project with dates is tracking its calendar.')
        : (behind === 1
            ? gs.getMessage('One project is meaningfully behind its calendar.')
            : behind + ' ' + gs.getMessage('projects are meaningfully behind their calendars.')));

  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title  : opt('label_title', gs.getMessage('My projects')),
    search : gs.getMessage('Search by project, program or reference'),

    tabAll    : gs.getMessage('All'),
    tabActive : gs.getMessage('In delivery'),
    tabDone   : gs.getMessage('Closed'),
    tabStopped: gs.getMessage('Cancelled'),

    attnTitle: gs.getMessage('Needs your attention'),
    attnHint : gs.getMessage('Projects reporting badly, running past their date, or that have gone quiet'),
    attnClear: gs.getMessage('Nothing needs attention'),

    gapTitle : gs.getMessage('Delivery against the calendar'),
    gapHint  : gs.getMessage('Two points per project: how much of the schedule has gone, and how much of the work is done. The distance between them is the story.'),
    gapNone  : gs.getMessage('No project has both a start and a planned end date yet, so there is nothing to plot.'),
    gapDone  : gs.getMessage('Work complete'),
    gapTime  : gs.getMessage('Schedule elapsed'),
    gapNoDate: gs.getMessage('No dates set, so not plotted'),
    gapPoints: gs.getMessage('points'),

    listTitle: gs.getMessage('All projects'),
    listHint : gs.getMessage('Sorted by last update'),

    manager  : gs.getMessage('Program manager'),
    started  : gs.getMessage('Started'),
    dueBy    : gs.getMessage('Due'),
    overdue  : gs.getMessage('overdue'),
    daysLeft : gs.getMessage('days left'),
    complete : gs.getMessage('complete'),
    notSet   : gs.getMessage('Not set'),

    cReports: gs.getMessage('Reports'),
    cChanges: gs.getMessage('Changes'),
    cClaims : gs.getMessage('Claims'),
    cRisks  : gs.getMessage('Risks'),
    cIssues : gs.getMessage('Issues'),

    view   : gs.getMessage('View project'),
    opening: gs.getMessage('Opening'),
    close  : gs.getMessage('Close'),

    mOverview  : gs.getMessage('Overview'),
    mDates     : gs.getMessage('Dates'),
    mLatest    : gs.getMessage('Latest status report'),
    mReports   : gs.getMessage('Status reports'),
    mChanges   : gs.getMessage('Change requests'),
    mClaims    : gs.getMessage('Reimbursements'),
    mRisks     : gs.getMessage('Risks'),
    mIssues    : gs.getMessage('Issues'),
    mNotes     : gs.getMessage('Notes'),

    mProgram   : gs.getMessage('Program'),
    mAward     : gs.getMessage('Award'),
    mApplicant : gs.getMessage('Application'),
    mPhase     : gs.getMessage('Phase'),
    mHealth    : gs.getMessage('Health'),
    mPercent   : gs.getMessage('Percent complete'),
    mReference : gs.getMessage('Reference'),
    mDesc      : gs.getMessage('Description'),

    mActualStart : gs.getMessage('Actual start'),
    mPlannedStart: gs.getMessage('Planned start'),
    mActualEnd   : gs.getMessage('Actual end'),
    mPlannedEnd  : gs.getMessage('Planned end'),

    mSchedule : gs.getMessage('Schedule'),
    mCost     : gs.getMessage('Cost'),
    mResources: gs.getMessage('Resources'),
    mScope    : gs.getMessage('Scope'),
    mSummary  : gs.getMessage('Executive summary'),
    mAchieved : gs.getMessage('Achievements last month'),
    mNextUp   : gs.getMessage('Key activities next month'),

    mApproval : gs.getMessage('Approval'),
    mCategory : gs.getMessage('Category'),
    mPriority : gs.getMessage('Priority'),
    mImpact   : gs.getMessage('Impact'),
    mAmount   : gs.getMessage('Amount'),
    mStatus   : gs.getMessage('Status'),
    mRaised   : gs.getMessage('Raised'),
    mNone     : gs.getMessage('Not provided'),
    mEmptyList: gs.getMessage('Nothing recorded'),

    emptyTitle: gs.getMessage('No projects yet'),
    emptyText : gs.getMessage('A project opens once you accept an award. Everything after that, reports, claims and changes, runs from here.'),
    emptyBtn  : gs.getMessage('Go to my awards'),

    noMatch    : gs.getMessage('Nothing matches this filter'),
    noMatchText: gs.getMessage('Try another tab, or clear the search.'),
    clear      : gs.getMessage('Clear')
  };

  data.pages = {
    awards: opt('awards_page', 'awards')
  };

  /* the widget the list hands off to when a project is opened */
  data.detailWidget = opt('detail_widget', 'each_project_detail');

})();
